def kleurenset_ids(style_config) -> set[str]:
    """Verzamel de kleurenset-id's waar een stijlconfiguratie naar verwijst.

    Parameters
    ----------
    style_config : object
        De JSON-waarde van ``spatial_style.style_config`` (willekeurig genest).

    Returns
    -------
    set of str
        Alle waarden onder een sleutel ``kleurensetId``, als tekst.
    """
    gevonden: set[str] = set()
    if isinstance(style_config, dict):
        for sleutel, waarde in style_config.items():
            if sleutel == "kleurensetId" and waarde:
                gevonden.add(str(waarde))
            else:
                gevonden |= kleurenset_ids(waarde)
    elif isinstance(style_config, list):
        for waarde in style_config:
            gevonden |= kleurenset_ids(waarde)
    return gevonden


def enige_organisatie(scopes) -> int | None:
    """Geef de organisatie als alle gebruikende lagen van precies die ene zijn.

    Parameters
    ----------
    scopes : iterable of tuple of (str, int or None)
        ``(access_through, access_id)`` van elke laag die de rij gebruikt.

    Returns
    -------
    int or None
        Het organisatie-id, of ``None`` als er geen laag is, een laag
        applicatiebreed is of de lagen van verschillende organisaties zijn.
    """
    scopes = set(scopes)
    if len(scopes) != 1:
        return None
    via, org_id = next(iter(scopes))
    return org_id if via == ORGANISATIE and org_id is not None else None


def wijs_scope_toe(apps, schema_editor):
    """Geef bestaande stijlen, kleurensets en koppelrijen hun scope.

    Koppelrijen krijgen de scope van hun laag. Een stijl of kleurenset wordt
    applicatiebreed, behalve als hij uitsluitend door lagen van precies één
    organisatie wordt gebruikt: dan gaat hij naar die organisatie. Er wordt
    niets verwijderd of gekopieerd.

    Parameters
    ----------
    apps : django.apps.registry.Apps
        Historische app-registry van de migratie.
    schema_editor : django.db.backends.base.schema.BaseDatabaseSchemaEditor
        Niet gebruikt.
    """
    Koppeling = apps.get_model("rgs_django_spatial", "SpatialLayerStyle")
    Stijl = apps.get_model("rgs_django_spatial", "SpatialStyle")
    Kleurenset = apps.get_model("rgs_django_spatial", "SpatialKleurenset")

    lagen_per_stijl: dict = {}
    for koppeling_id, stijl_id, via, org_id in Koppeling.objects.values_list(
        "id", "style_id", "layer__access_through_id", "layer__access_id"
    ):
        if via == ORGANISATIE:
            Koppeling.objects.filter(pk=koppeling_id).update(access_through_id=ORGANISATIE, access_id=org_id)
        if stijl_id is not None:
            lagen_per_stijl.setdefault(stijl_id, set()).add((via, org_id))

    lagen_per_kleurenset: dict = {}
    for stijl_id, config in Stijl.objects.values_list("id", "style_config"):
        scopes = lagen_per_stijl.get(stijl_id, set())
        org_id = enige_organisatie(scopes)
        if org_id is not None:
            Stijl.objects.filter(pk=stijl_id).update(access_through_id=ORGANISATIE, access_id=org_id)
        for kleurenset_id in kleurenset_ids(config):
            # Een stijl zonder laag telt niet mee: die zegt niets over wie hem gebruikt.
            lagen_per_kleurenset.setdefault(kleurenset_id, set()).update(scopes)

    for kleurenset_id in Kleurenset.objects.values_list("id", flat=True):
        org_id = enige_organisatie(lagen_per_kleurenset.get(str(kleurenset_id), set()))
        if org_id is not None:
            Kleurenset.objects.filter(pk=kleurenset_id).update(access_through_id=ORGANISATIE, access_id=org_id)


